def main():
	i = input().split()
	(size, moves, reach) = (int(i[0]), int(i[1]), int(i[2]))
	board = []
	for r in range(size):
		data = input()
		if data.find('L') != -1:
			locationR = r
			locationC = data.find('L')
		board.append(data)
	ways = []
	for moveNum in range(moves + 1):
		tboard = []
		if moveNum == 0:
			for i in range(size):
				row = []
				for j in range(size):
					if board[i][j] != 'P':
						row.append(1)
					else:
						row.append(0)
				tboard.append(row)
		else:
			for i in range(size):
				row = []
				for j in range(size):
					if board[i][j] == 'P':
						row.append(0)
						continue
					total = 0
					for r in range(max(0, i - reach), min(size, i + reach + 1)):
						for c in range(max(0, j - reach + abs(r - i)), min(size, j + reach - abs(r - i) + 1)):
							total += ways[moveNum - 1][r][c]
					row.append(total)
				tboard.append(row)
		ways.append(tboard)
	return ways[-1][locationR][locationC]
for _ in range(int(input())):
	print(main())
